{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) client_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,1) server_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel2-service' AND c.attr_span_kind='Client' GROUP BY ALL ORDER BY 1,2", "claim": "travel2's client POST to seat left_tickets takes about 3534 ms at p50, while seat's server span is about 17 ms."},
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) client_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel2-service' AND c.attr_span_kind='Client' AND s.service_name='ts-basic-service' GROUP BY ALL", "claim": "The same travel2 pod's calls to basic-service stay near 40 ms, so only the seat path is slowed."},
        {"kind": "metric", "sql": "SELECT metric, attr_source, attr_destination, round(avg(sum/NULLIF(count,0)),4) avg_s FROM abnormal_metrics_histogram WHERE metric='hubble_http_request_duration_seconds' AND attr_source LIKE '%travel2%' AND attr_destination LIKE '%seat%' GROUP BY ALL", "claim": "Hubble HTTP request duration travel2→seat stays about 39 ms, same as normal, so the wire is not slow."},
        {"kind": "metric", "sql": "SELECT metric, round(avg(value),3) avgv, round(max(value),3) maxv FROM abnormal_metrics WHERE service_name='ts-travel2-service' AND metric IN ('k8s.container.restarts','container.cpu.usage') GROUP BY 1", "claim": "travel2 shows no restarts and low CPU in the abnormal period, so it is not resource saturation."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) client_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,1) server_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-travel2-service' GROUP BY ALL ORDER BY 1,2", "claim": "route-plan's client calls to travel2 trips/left and trip_detail take about 7.1 s, matching travel2's server time."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) client_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,1) server_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-route-plan-service' GROUP BY ALL ORDER BY 1,2", "claim": "travel-plan's client calls to route-plan take about 7.2 s, matching route-plan's server time."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY ALL ORDER BY 1,2", "claim": "User-facing travelPlan requests at ui-dashboard take 6-7 s at p50, following travel-plan's server time."}]},
    {"from": "ts-travel2-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT s.service_name, s.span_name, count(*) n, sum(CASE WHEN s.attr_status_code='Error' OR s.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) errors, round(approx_quantile(s.duration,0.5)/1e6,1) p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel2-service' GROUP BY ALL", "claim": "ui-dashboard calls to travel2 trips/left are slow (multi-second) and include 500 errors from travel2."}]}
  ]
}
